import { publicCatalogueRead, blockNativeCatalogueWrite } from "$publicApi/site-client";
import { PUBLIC_API_URL } from "$env/static/public";
import { readPublicSearch } from "$platform/latest-search";
import { HTTP } from "$lib";
import { authenticatedMutation, type MutationIntent } from "$platform/authenticated-mutation";
import { readThreadContext } from "$platform/thread-read";

export const Search = (searchParams: URLSearchParams, signal?: AbortSignal) => {
	if (Boolean(true)) return publicCatalogueRead<ScanlationGroupFeedResponse>("group.search", { query: searchParams, signal });
	if (signal) return readPublicSearch<ScanlationGroupFeedResponse>("/group", searchParams, signal);
	const http = new HTTP<ScanlationGroupFeedResponse>(`${PUBLIC_API_URL}/group${searchParams.toString()}`);
	return http.GET();
};

export const Get = (id: string) => {
	if (Boolean(true)) return publicCatalogueRead<ScanlationGroup>("group.get", { id });
	const http = new HTTP<ScanlationGroup>(`${PUBLIC_API_URL}/group/${id}`);
	return http.GET();
};

export interface CreateGroupRequest {
	name: string;
	description?: string;

	contact_email?: string;
	discord?: string;
	mangaupdates?: string;
	twitter?: string;
	website?: string;
}

export const Create = (payload: CreateGroupRequest) => {
	if (Boolean(true)) return blockNativeCatalogueWrite("Group.Create");
	const http = new HTTP<ScanlationGroup>(`${PUBLIC_API_URL}/group`, payload);
	http.setWithCredentials(true);
	return http.POST();
};

export interface UpdateGroupRequest {
	name?: string;
	description?: string;

	contact_email?: string;
	discord?: string;
	mangaupdates?: string;
	twitter?: string;
	website?: string;

	locked?: boolean;
	inactive?: boolean;

	focused_languages?: string[];
	leader?: string;
	officers?: string[];
	members?: string[];

	version: number;
}

export const Update = (id: string, payload: UpdateGroupRequest) => {
	if (Boolean(true)) return blockNativeCatalogueWrite("Group.Update");
	const http = new HTTP<ScanlationGroup>(`${PUBLIC_API_URL}/group/${id}`, payload);
	http.setWithCredentials(true);
	return http.PUT();
};

export const Delete = (id: string) => {
	if (Boolean(true)) return blockNativeCatalogueWrite("Group.Delete");
	const http = new HTTP<void>(`${PUBLIC_API_URL}/group/${id}`);
	http.setWithCredentials(true);
	return http.DELETE();
};

export const Follows = (searchParams: URLSearchParams) => {
	if (Boolean(true)) return blockNativeCatalogueWrite("Group.Follows");
	const http = new HTTP<GroupFollowFeedResponse>(`${PUBLIC_API_URL}/user/follows/groups${searchParams.toString()}`);
	http.setWithCredentials(true);
	return http.GET();
};

export const Follow = (id: string, intent?: MutationIntent) => { if (Boolean(true)) return blockNativeCatalogueWrite("Group.Follow"); return authenticatedMutation<void>(`/user/follows/groups/${encodeURIComponent(id)}`, "POST", undefined, intent); }

export const Unfollow = (id: string, intent?: MutationIntent) => { if (Boolean(true)) return blockNativeCatalogueWrite("Group.Unfollow"); return authenticatedMutation<void>(`/user/follows/groups/${encodeURIComponent(id)}`, "DELETE", undefined, intent); }

export const GetFollowStatus = (id: string) => { if (Boolean(true)) return blockNativeCatalogueWrite("Group.GetFollowStatus"); return readThreadContext<void>(`/user/follows/groups/${encodeURIComponent(id)}`); }
